//! Full native saves generated by their historical engines before the ordering rules changed.
use super::prevention_order_no_hallow_v1::{choose_public, combat_choice};
use super::{life, restored, settled, shields, Action, Decision, GameState, Target, P0, P1};

fn load(bytes: &[u8]) -> GameState {
    serde_json::from_reader(flate2::read::GzDecoder::new(bytes)).unwrap()
}

// Produced by fdb210d57 with real Strands (red), Hallow on Sprite, and a
// Nishoba double-blocked by Grim Lavamancer then Spellstutter Sprite.
#[test]
fn pre_868_combat_save_keeps_the_sprite_choice_and_both_original_outcomes() {
    let state = load(include_bytes!("fixtures/hallow_combat_fdb210d57.json.gz"));
    let pending = state
        .engine
        .linked_aura_operation_v1
        .pending_hallow_v1
        .as_ref()
        .unwrap();
    let sprite = pending.choice.damage.source;
    let Target::Object(nishoba) = pending.choice.damage.target else {
        panic!("expected the attacker")
    };
    assert_eq!(state.objects.get(sprite).name, "Spellstutter Sprite");
    assert!(!pending.expanded_damage_order);
    for (option, life_total, old_hash) in [
        (0, 28, 775_449_924_781_070_392),
        (1, 27, 15_543_001_243_817_850_795),
    ] {
        let mut branch = restored(&state);
        choose_public(&mut branch, P0, sprite, option, 2);
        assert!(combat_choice(&mut branch).is_none());
        assert_eq!(life(&branch, P0), life_total);
        assert_eq!(branch.objects.get(nishoba).counters.plus1_plus1, 6);
        assert_eq!(branch.state_hash(), old_hash);
    }
    let mut fresh = (*pending.original).clone();
    let Some(Decision::ChooseEffectOption {
        player: P0,
        source,
        option_count: 2,
    }) = combat_choice(&mut fresh)
    else {
        panic!("fresh combat should offer Strands or Nishoba first")
    };
    assert_eq!(fresh.objects.get(source).name, "Grim Lavamancer");
    assert!(
        fresh
            .engine
            .linked_aura_operation_v1
            .pending_hallow_v1
            .as_ref()
            .unwrap()
            .expanded_damage_order
    );

    let mut altered = restored(&state);
    altered
        .engine
        .linked_aura_operation_v1
        .pending_hallow_v1
        .as_mut()
        .unwrap()
        .choice
        .chooser = P1;
    assert!(mtg_kernel::engine::step(&mut altered, Action::ChooseEffectOption(0)).is_err());
    let mut altered = restored(&state);
    altered.players[0].life -= 1;
    assert!(mtg_kernel::engine::step(&mut altered, Action::ChooseEffectOption(0)).is_err());
}

// The paid red Circle on the first attacker, Jackal Pup, was automatic in W1.
// Defender's recorded choice concerned the second attacker, Hallowed Ball Lightning.
#[test]
fn w1_fog_keeps_the_later_hallowed_attacker_before_the_circle_global_frontier() {
    let state = load(include_bytes!("fixtures/hallow_combat_16ef09699.json.gz"));
    let pending = state
        .engine
        .linked_aura_operation_v1
        .pending_hallow_v1
        .as_ref()
        .unwrap();
    let ball = pending.choice.damage.source;
    assert_eq!(state.objects.get(ball).name, "Ball Lightning");
    for (option, total, old_hash) in [
        (0, 26, 2_038_007_262_687_466_995),
        (1, 20, 13_281_683_953_369_186_478),
    ] {
        let mut branch = restored(&state);
        choose_public(&mut branch, P1, ball, option, 2);
        assert!(combat_choice(&mut branch).is_none());
        assert_eq!((life(&branch, P1), shields(&branch)), (total, 0));
        assert_eq!(branch.state_hash(), old_hash);
    }
    let mut fresh = (*pending.original).clone();
    assert!(
        matches!(combat_choice(&mut fresh),Some(Decision::ChooseEffectOption{player:P1,source,option_count:2}) if fresh.objects.get(source).name=="Jackal Pup")
    );
}

// 10c8c80c5 offered the order of Ojer and two Spheres on a one-point Lava Dart.
// Both choices finished at the same total before that redundant menu was removed.
#[test]
fn published_sphere_ojer_menu_resumes_both_previously_offered_orders() {
    let state = load(include_bytes!("fixtures/damage_order_10c8c80c5.json.gz"));
    let source = state
        .engine
        .linked_aura_operation_v1
        .pending_hallow_v1
        .as_ref()
        .unwrap()
        .choice
        .damage
        .source;
    assert_eq!(state.objects.get(source).name, "Lava Dart");
    for option in [0, 1] {
        let mut branch = restored(&state);
        choose_public(&mut branch, P1, source, option, 2);
        settled(&mut branch);
        assert_eq!(life(&branch, P1), 20);
        assert_eq!(branch.state_hash(), 17_688_977_802_951_398_691);
    }
}
